# our updated program here
import numpy as np
import time
import random
from typing import List, Tuple, Dict, Set

class CVRPSolver:
    def __init__(self, coordinates: np.ndarray, distance_matrix: np.ndarray, demands: list, vehicle_capacity: int):
        """
        Initialize the CVRP solver.

        Args:
            coordinates: Numpy array of shape (n, 2) containing the (x, y) coordinates of each node, including the depot.
            distance_matrix: Numpy array of shape (n, n) containing pairwise distances between nodes.
            demands: List of integers representing the demand of each node (first node is typically the depot with zero demand).
            vehicle_capacity: Integer representing the maximum capacity of each vehicle.
        """
        self.coordinates = coordinates
        self.distance_matrix = distance_matrix
        self.demands = demands
        self.vehicle_capacity = vehicle_capacity
        self.n = len(coordinates)
        # safety checks
        if len(distance_matrix) != self.n or len(demands) != self.n:
            raise ValueError("Mismatch in input sizes")

    # ------------------ Helper methods ------------------

    def _routes_to_flat(self, routes: List[List[int]]) -> List[int]:
        flat = []
        for r in routes:
            if len(r) == 0:
                continue
            if r[0] != 0:
                flat.append(0)
            for v in r:
                flat.append(v)
            if r[-1] != 0:
                flat.append(0)
        if len(flat) == 0:
            flat = [0, 0]
        if flat[0] != 0:
            flat.insert(0, 0)
        if flat[-1] != 0:
            flat.append(0)
        return flat

    def _flat_to_routes(self, flat: List[int]) -> List[List[int]]:
        routes = []
        cur = []
        for v in flat:
            if v == 0:
                if cur:
                    routes.append([0] + cur + [0])
                    cur = []
            else:
                cur.append(v)
        if cur:
            routes.append([0] + cur + [0])
        if not routes:
            routes = [[0, 0]]
        return routes

    def _evaluate_routes(self, routes: List[List[int]]) -> float:
        cost = 0.0
        for r in routes:
            for i in range(len(r)-1):
                cost += self.distance_matrix[r[i], r[i+1]]
        return cost

    def _route_demand(self, route: List[int]) -> int:
        # route includes depot at start and end
        return sum(self.demands[v] for v in route if v != 0)

    # ------------------ Encoding / Duals / Relaxation ------------------

    def _encode_problem(self):
        model = {
            "n": self.n,
            "dist": self.distance_matrix,
            "demands": self.demands,
            "capacity": self.vehicle_capacity
        }
        return model

    def _init_duals(self, model):
        # dual for each customer (including depot for convenience)
        return np.zeros(model["n"], dtype=float)

    def _build_lagrangian_relaxation(self, model, lambdas):
        # Relaxation represented by reduced costs for edges:
        # reduced_cost[i,j] = dist[i,j] + lambda[i] + lambda[j]
        dist = model["dist"]
        n = model["n"]
        rc = np.empty_like(dist)
        for i in range(n):
            # broadcast
            rc[i, :] = dist[i, :] + lambdas[i] + lambdas
        return rc

    def _solve_relaxed_problem_approx(self, rc: np.ndarray, params):
        # For approx solution we compute:
        # - minimal reduced cost neighbor for each node (reduced_info)
        # - a greedy pairing/matching by smallest reduced edges
        n = rc.shape[0]
        reduced_info = {
            "min_rc_to": np.min(rc, axis=1),
            "min_rc_idx": np.argmin(rc, axis=1)
        }
        # Build a simple greedy matching of customers (excluding depot 0) based on rc
        pairs = []
        seen = set([0])
        node_list = list(range(1, n))
        # create sorted edges among customers by reduced cost
        edges = []
        for i in range(1, n):
            for j in range(i+1, n):
                edges.append((rc[i, j], i, j))
        edges.sort(key=lambda x: x[0])
        for c, i, j in edges:
            if i in seen or j in seen:
                continue
            pairs.append((i, j))
            seen.add(i); seen.add(j)
        # add remaining singletons
        for i in range(1, n):
            if i not in seen:
                pairs.append((i,))
                seen.add(i)
        dual_solution = {"pairs": pairs}
        return dual_solution, reduced_info

    # ------------------ Greedy construction (Clarke-Wright) ------------------

    def _construct_greedy(self, model, params):
        dist = model["dist"]
        demands = model["demands"]
        capacity = model["capacity"]
        n = model["n"]
        # Start with each customer in its own route [0,i,0]
        routes = []
        for i in range(1, n):
            routes.append([0, i, 0])
        # compute savings
        savings = []
        for i in range(1, n):
            for j in range(i+1, n):
                s = dist[0, i] + dist[0, j] - dist[i, j]
                savings.append((s, i, j))
        savings.sort(reverse=True, key=lambda x: x[0])
        # helper to find route index and whether node is at start or end
        def find_route_and_pos(node):
            for idx, r in enumerate(routes):
                if node in r:
                    # return idx and position excluding depots
                    if r[1] == node:
                        pos = "start"
                    elif r[-2] == node:
                        pos = "end"
                    else:
                        pos = "middle"
                    return idx, pos
            return None, None

        for s, i, j in savings:
            ri, posi = find_route_and_pos(i)
            rj, posj = find_route_and_pos(j)
            if ri is None or rj is None or ri == rj:
                continue
            if posi == "middle" or posj == "middle":
                continue
            # Merge if i is at end of ri and j at start of rj (or vice versa)
            merged = None
            if posi == "end" and posj == "start":
                # check capacity
                demand_ri = self._route_demand(routes[ri])
                demand_rj = self._route_demand(routes[rj])
                if demand_ri + demand_rj <= capacity:
                    # merge ri + rj (drop duplicate depot)
                    newr = routes[ri][:-1] + routes[rj][1:]
                    merged = newr
            elif posj == "end" and posi == "start":
                demand_ri = self._route_demand(routes[ri])
                demand_rj = self._route_demand(routes[rj])
                if demand_ri + demand_rj <= capacity:
                    newr = routes[rj][:-1] + routes[ri][1:]
                    merged = newr
            if merged is not None:
                # replace routes ri and rj with merged (ensure index ordering)
                a, b = sorted([ri, rj], reverse=True)
                # remove higher index first
                routes.pop(a)
                routes.pop(b)
                routes.append(merged)
        # ensure feasibility (if some route exceeds capacity, split greedily)
        final_routes = []
        for r in routes:
            if self._route_demand(r) <= capacity:
                final_routes.append(r)
            else:
                # split into multiple via simple greedy fill
                customers = [v for v in r if v != 0]
                cur = [0]
                cap = 0
                for v in customers:
                    if cap + self.demands[v] > capacity:
                        cur.append(0)
                        final_routes.append(cur)
                        cur = [0]
                        cap = 0
                    cur.append(v)
                    cap += self.demands[v]
                if cur[-1] != 0:
                    cur.append(0)
                final_routes.append(cur)
        # return flat representation
        return self._routes_to_flat(final_routes)

    # ------------------ Neighborhood identification ------------------

    def _identify_promising_neighborhoods(self, dual_solution, reduced_info, lambdas, model, params):
        # Using reduced_info["min_rc_to"], pick nodes with smallest reduced costs
        n = model["n"]
        min_rc = reduced_info["min_rc_to"]
        # rank customers except depot
        idx = list(range(1, n))
        idx.sort(key=lambda i: min_rc[i])
        neighborhoods = []
        # adaptively choose sizes
        top_k = min(params.get("top_k", max(3, n//10)), len(idx))
        # create neighborhoods: for each top candidate, include its nearest neighbors by distance
        for i in idx[:top_k]:
            neigh_size = params.get("nbhd_radius", max(3, n//8))
            # find nearest by real distance
            dists = model["dist"][i]
            neighbors = np.argsort(dists)[1:1+neigh_size]  # exclude itself maybe include depot
            nb_set = set(int(x) for x in neighbors if x != 0)
            nb_set.add(int(i))
            neighborhoods.append(nb_set)
        # also add some random neighborhoods for diversification
        for _ in range(params.get("random_nb", 2)):
            size = min(params.get("nbhd_random_size", max(3, n//10)), n-1)
            sample = set(random.sample(range(1, n), size))
            neighborhoods.append(sample)
        return neighborhoods

    # ------------------ Large neighborhood repair (destroy & repair) ------------------

    def _large_neighborhood_repair(self, incumbent_flat, neighborhoods, reduced_info, model, params):
        """
        Large Neighborhood Search style repair operator for CVRP.

        Improvements over the original:
        - More robust RNG abstraction (supports numpy Generator/RandomState and python random).
        - Safe distance accessor that supports numpy arrays and nested lists.
        - Clearer control flow and defensive checks for malformed input.
        - Slightly improved regret scoring with small tie-breaking noise to avoid deterministic stalls.
        - Fewer repeated imports and clearer defaults for optional params.
        - Comments and small micro-optimizations for readability and maintainability.

        Inputs/Outputs are the same as original function:
        - incumbent_flat: flattened solution representation used by the larger program.
        - neighborhoods: list of neighborhoods (each a sequence of node indices) to consider removing.
        - reduced_info: dictionary that may contain "min_rc_to" etc.
        - model: dictionary containing at least keys "n", "dist", "demands", "capacity".
        - params: dictionary of optional parameters (rng, greedy_nb_prob, lambda_weight, etc.)

        Returns: flattened solution in the same format as incumbent_flat.
        """
        import math
        import random

        # Defensive model unpacking
        if model is None or "n" not in model:
            return incumbent_flat.copy()
        n = int(model["n"])
        dist = model.get("dist")
        demands = model.get("demands")
        capacity = model.get("capacity")

        if dist is None or demands is None or capacity is None:
            return incumbent_flat.copy()

        # Distance accessor that supports numpy arrays and nested lists
        def _d(a, b):
            try:
                return dist[a, b]
            except Exception:
                return dist[a][b]

        # RNG abstraction: accept numpy Generator/RandomState or python random module/object
        rng = params.get("rng", None)
        use_numpy = False
        if rng is None:
            try:
                import numpy as _np
                rng = _np.random
                use_numpy = True
            except Exception:
                rng = random
        else:
            # detect numpy-like RNG
            try:
                import numpy as _np  # type: ignore
                if isinstance(rng, (_np.random.Generator, _np.random.RandomState)) or hasattr(rng, "choice"):
                    use_numpy = True
            except Exception:
                use_numpy = False

        def _rand():
            if use_numpy and hasattr(rng, "random"):
                return float(rng.random())
            if hasattr(rng, "random"):
                return float(rng.random())
            return random.random()

        def _choice_index(weights):
            """Return an index sampled according to weights (list-like nonnegative)."""
            if use_numpy and hasattr(rng, "choice"):
                probs = None
                w = weights
                s = float(sum(w))
                if s > 0:
                    probs = [float(x) / s for x in w]
                else:
                    probs = None
                return int(rng.choice(len(w), p=probs))
            # fallback: cumulative sampling with python random
            s = float(sum(weights))
            if s <= 0:
                return random.randrange(len(weights))
            r = random.random() * s
            cum = 0.0
            for i, wi in enumerate(weights):
                cum += float(wi)
                if r <= cum:
                    return i
            return len(weights) - 1

        def _shuffle_inplace(seq):
            if use_numpy and hasattr(rng, "shuffle"):
                try:
                    rng.shuffle(seq)
                    return
                except Exception:
                    pass
            random.shuffle(seq)

        # Quick return if no neighborhoods
        if not neighborhoods:
            return incumbent_flat.copy()

        # Prepare min_rc array (reduce to python list for light-weight ops)
        min_rc = reduced_info.get("min_rc_to")
        if min_rc is None:
            min_rc_list = [0.0] * n
        else:
            try:
                min_rc_list = [float(min_rc[i]) if 0 <= i < len(min_rc) else 0.0 for i in range(n)]
            except Exception:
                # fallback
                min_rc_list = [0.0] * n

        # Score neighborhoods by average reduced cost of contained customers (exclude depot 0)
        scores = []
        for nb in neighborhoods:
            if not nb:
                scores.append(0.0)
                continue
            vals = []
            for i in nb:
                if 1 <= i < n:
                    vals.append(min_rc_list[i])
            scores.append(float(sum(vals) / len(vals)) if vals else 0.0)

        greedy_prob = float(params.get("greedy_nb_prob", 0.8))
        if _rand() < greedy_prob:
            # choose argmax score (tie broken by first occurrence)
            best_idx = int(max(range(len(scores)), key=lambda i: scores[i]))
        else:
            # probabilistic choice proportional to positive-shifted scores
            arr = [float(s) for s in scores]
            mn = min(arr) if arr else 0.0
            shifted = [a - mn + 1e-9 for a in arr]
            ssum = sum(shifted)
            if ssum <= 0:
                probs = [1.0 / len(shifted)] * len(shifted)
            else:
                probs = [x / ssum for x in shifted]
            best_idx = _choice_index(probs)

        best_nb = neighborhoods[best_idx] if 0 <= best_idx < len(neighborhoods) else []

        # Removal set (unique, valid customers only, exclude depot 0)
        removed_set = {int(v) for v in best_nb if v != 0 and 1 <= int(v) < n}

        # Convert incumbent to routes (self method expected to exist)
        routes = self._flat_to_routes(incumbent_flat)

        # Build new_routes by removing nodes in removed_set; collect removed_list preserving first-appearance order
        new_routes = []
        removed_list = []
        seen_removed = set()
        for r in routes:
            r = list(r)
            # record removed nodes in their order of appearance (first time only)
            for v in r:
                if v in removed_set and v != 0 and v not in seen_removed:
                    removed_list.append(v)
                    seen_removed.add(v)
            # create route without removed nodes
            newr = [v for v in r if v not in removed_set]
            # ensure valid route (must contain at least depot at start and end)
            if not newr:
                continue
            if newr[0] != 0:
                newr.insert(0, 0)
            if newr[-1] != 0:
                newr.append(0)
            # discard trivial routes containing only depots
            if len(newr) <= 2:
                continue
            new_routes.append(newr)

        # Diversify insertion order
        _shuffle_inplace(removed_list)

        # Repair parameters and lambdas
        import math as _math
        try:
            import numpy as _np  # optional
        except Exception:
            _np = None

        lambdas = params.get("_lambdas_for_repair", None)
        if lambdas is None:
            lambda_list = [0.0] * n
        else:
            # try to convert to list of floats
            try:
                lambda_list = [float(lambdas[i]) if 0 <= i < len(lambdas) else 0.0 for i in range(n)]
            except Exception:
                lambda_list = [0.0] * n

        lambda_w = float(params.get("lambda_weight", 0.5))
        new_route_bias = float(params.get("new_route_bias", 0.0))
        regret_k = max(1, int(params.get("regret_k", 2)))

        # Precompute demands of current routes (self._route_demand expected to exist)
        route_demands = [self._route_demand(r) for r in new_routes]

        # Helper: compute insertion options for node v, returning sorted list of (type, ri, pos, delta)
        def _insertion_options_for(v):
            dv = demands[v]
            opts = []
            # existing routes
            for ri, r in enumerate(new_routes):
                if route_demands[ri] + dv > capacity:
                    continue
                # positions between r[p] and r[p+1]; insert at index p+1
                for p in range(len(r) - 1):
                    a, b = r[p], r[p + 1]
                    delta = float(_d(a, v) + _d(v, b) - _d(a, b) + lambda_list[v] * lambda_w)
                    opts.append(("insert", ri, p + 1, delta))
            # new singleton route
            if dv <= capacity:
                delta_new = float(_d(0, v) + _d(v, 0) + lambda_list[v] * lambda_w + new_route_bias)
                opts.append(("new", None, None, delta_new))
            if not opts:
                return []
            opts.sort(key=lambda x: x[3])
            return opts

        # Regret-k insertion loop
        # Note: removed_list contains unique nodes to insert
        while removed_list:
            best_node = None
            best_choice = None
            best_score = -math.inf

            # Evaluate regret score for each candidate; we add tiny noise to break ties deterministically
            for v in removed_list:
                opts = _insertion_options_for(v)
                if not opts:
                    continue
                topk = opts[:regret_k]
                best_cost = topk[0][3]
                if len(topk) >= 2:
                    regret = topk[1][3] - topk[0][3]
                else:
                    # If no alternative, prioritize nodes whose best cost is relatively high (hard to place)
                    regret = -best_cost
                # score: larger regret increases priority; prefer smaller best_cost; add tiny noise
                tie_noise = (0.0 if _np is None else float((_np.random.random() - 0.5) * 1e-6))
                score = regret - 0.05 * best_cost + tie_noise
                if score > best_score:
                    best_score = score
                    best_node = v
                    best_choice = topk[0]

            if best_node is None:
                # No feasible insertions into current routes -> try creating new singleton routes for feasible nodes
                placed_any = False
                for v in removed_list[:]:
                    if demands[v] <= capacity:
                        new_routes.append([0, v, 0])
                        route_demands.append(demands[v])
                        removed_list.remove(v)
                        placed_any = True
                if not placed_any:
                    # cannot place remaining nodes (likely demand > capacity); stop to avoid infinite loop
                    break
                else:
                    continue

            typ, ri, pos, _c = best_choice
            if typ == "new":
                new_routes.append([0, best_node, 0])
                route_demands.append(demands[best_node])
            else:
                # sanity check ri and pos
                if not (0 <= ri < len(new_routes)):
                    # fallback to creating new route if target route disappeared
                    new_routes.append([0, best_node, 0])
                    route_demands.append(demands[best_node])
                else:
                    new_routes[ri].insert(pos, best_node)
                    route_demands[ri] += demands[best_node]

            removed_list.remove(best_node)

        # Light post-processing: single-node inter-route relocation
        improved = True
        it = 0
        max_it = max(1, int(params.get("post_improve_iters", 8)))
        while improved and it < max_it:
            improved = False
            it += 1
            outer_ri = 0
            # Iterate while allowing modifications to new_routes
            while outer_ri < len(new_routes):
                r = new_routes[outer_ri]
                if len(r) <= 3:
                    outer_ri += 1
                    continue
                moved = False
                # Try each customer in route (skip depot endpoints)
                for idx in range(1, len(r) - 1):
                    v = r[idx]
                    dv = demands[v]
                    a0, b0 = r[idx - 1], r[idx + 1]
                    delta_rem = float(_d(a0, b0) - (_d(a0, v) + _d(v, b0)))
                    best_move = None
                    best_delta = 0.0
                    # Try all other routes insertions
                    for to_rj in range(len(new_routes)):
                        if to_rj == outer_ri:
                            continue
                        if route_demands[to_rj] + dv > capacity:
                            continue
                        r2 = new_routes[to_rj]
                        # possible insertion positions between r2[p-1] and r2[p]
                        for p in range(1, len(r2)):
                            a, b = r2[p - 1], r2[p]
                            delta_ins = float(_d(a, v) + _d(v, b) - _d(a, b) + lambda_list[v] * (lambda_w * 0.5))
                            delta = delta_rem + delta_ins
                            if delta < best_delta:
                                best_delta = delta
                                best_move = (outer_ri, idx, to_rj, p, delta)
                    if best_move:
                        from_ri, from_idx, to_rj, to_p, _ = best_move
                        vmove = new_routes[from_ri].pop(from_idx)
                        route_demands[from_ri] -= demands[vmove]
                        # Remove trivial routes (only depots)
                        if len(new_routes[from_ri]) <= 2:
                            del new_routes[from_ri]
                            del route_demands[from_ri]
                            # Adjust destination index if it was after removed route
                            if from_ri < to_rj:
                                to_rj -= 1
                        # Insert into destination route
                        new_routes[to_rj].insert(to_p, vmove)
                        route_demands[to_rj] += demands[vmove]
                        improved = True
                        moved = True
                        break  # restart after any successful local move
                if moved:
                    outer_ri = 0
                else:
                    outer_ri += 1

        # Intra-route 2-opt (bounded iterations)
        for ri in range(len(new_routes)):
            r = new_routes[ri]
            if len(r) <= 4:
                continue
            changed = True
            iter2 = 0
            while changed and iter2 < 5:
                iter2 += 1
                changed = False
                best_delta = 0.0
                best_pair = None
                L = len(r)
                # search for best improving 2-opt move
                for i in range(1, L - 2):
                    ai = r[i - 1]
                    bi = r[i]
                    for j in range(i + 1, L - 1):
                        cj = r[j]
                        dj = r[j + 1]
                        delta = float((_d(ai, cj) + _d(bi, dj)) - (_d(ai, bi) + _d(cj, dj)))
                        if delta < best_delta:
                            best_delta = delta
                            best_pair = (i, j)
                if best_pair:
                    i, j = best_pair
                    # perform 2-opt (reverse segment)
                    r[i:j + 1] = list(reversed(r[i:j + 1]))
                    changed = True
            new_routes[ri] = r

        # Final cleanup: ensure all customers assigned; add singletons for missing feasible customers
        assigned = {v for r in new_routes for v in r if v != 0}
        all_customers = set(range(1, n))
        missing = sorted(list(all_customers - assigned))
        for v in missing:
            if demands[v] <= capacity:
                new_routes.append([0, v, 0])
            else:
                # If customer's demand exceeds capacity, we cannot place it here.
                # The larger program should handle infeasible instances.
                continue

        # Return flattened representation expected by rest of program
        return self._routes_to_flat(new_routes)

    # ------------------ Dual updates and adaptation ------------------

    def _update_duals(self, lambdas, dual_solution, candidate_flat, model, params):
        # Simple adaptive update:
        # Increase lambda for nodes that frequently appear in neighborhoods or that have high reduced cost
        step = params.get("dual_step", 0.1)
        # compute frequency heuristic from pairs
        freq = np.zeros_like(lambdas)
        for p in dual_solution.get("pairs", []):
            for v in p:
                if v >= 0 and v < len(freq):
                    freq[v] += 1.0
        # normalize
        if freq.max() > 0:
            freq = freq / (freq.max())
        # update: lambdas = max(0, lambdas + step*(freq - 0.5))
        lambdas = lambdas + step * (freq - 0.5)
        # small decay to avoid unbounded growth
        lambdas *= (1.0 - params.get("dual_decay", 0.01))
        # Clip to reasonable bounds
        lambdas = np.clip(lambdas, -params.get("lambda_clip", 50.0), params.get("lambda_clip", 50.0))
        return lambdas

    def _adapt_search_strategy(self, neighborhoods, lambdas, params):
        # adapt params based on stability of lambdas and number of neighborhoods
        lam_std = float(np.std(lambdas))
        if lam_std < params.get("lam_stable_thresh", 0.01):
            # little change -> diversify
            params["nbhd_radius"] = min(params.get("nbhd_radius", 5) + 1, max(5, self.n//4))
            params["random_nb"] = min(params.get("random_nb", 2) + 1, 5)
        else:
            # intensify
            params["nbhd_radius"] = max(3, params.get("nbhd_radius", 5) - 1)
            params["random_nb"] = max(1, params.get("random_nb", 2) - 1)
        # ensure sensible bounds
        params["nbhd_radius"] = int(max(3, min(params["nbhd_radius"], self.n-1)))
        params["random_nb"] = int(max(1, min(params["random_nb"], 6)))

    # ------------------ Main solver: DGLND-like loop ------------------

    def solve(self) -> list:
        """
        Solve the Capacitated Vehicle Routing Problem (CVRP).

        Returns:
            A one-dimensional list of integers representing the sequence of nodes visited by all vehicles.
        """
        model = self._encode_problem()
        # parameters
