    n = int(model["n"])
    dist = model.get("dist")
    demands = model.get("demands")
    capacity = model.get("capacity")

    if dist is None or demands is None or capacity is None:
        return incumbent_flat.copy()

    # Distance accessor that supports numpy arrays and nested lists
    def _d(a, b):
