            return dist[a, b]
        except Exception:
            return dist[a][b]

    # RNG abstraction: accept numpy Generator/RandomState or python random module/object
    rng = params.get("rng", None)
    use_numpy = False
    if rng is None:
        try:
            import numpy as _np
            rng = _np.random
            use_numpy = True
        except Exception:
            rng = random
    else:
        # detect numpy-like RNG
        try:
            import numpy as _np  # type: ignore
            if isinstance(rng, (_np.random.Generator, _np.random.RandomState)) or hasattr(rng, "choice"):
                use_numpy = True
        except Exception:
            use_numpy = False

    def _rand():
        if use_numpy and hasattr(rng, "random"):
            return float(rng.random())
        if hasattr(rng, "random"):
            return float(rng.random())
        return random.random()

    def _choice_index(weights):
        """Return an index sampled according to weights (list-like nonnegative)."""
        if use_numpy and hasattr(rng, "choice"):
            probs = None
            w = weights
            s = float(sum(w))
            if s > 0:
                probs = [float(x) / s for x in w]
            else:
                probs = None
            return int(rng.choice(len(w), p=probs))
        # fallback: cumulative sampling with python random
        s = float(sum(weights))
        if s <= 0:
            return random.randrange(len(weights))
        r = random.random() * s
        cum = 0.0
        for i, wi in enumerate(weights):
            cum += float(wi)
            if r <= cum:
                return i
        return len(weights) - 1

    def _shuffle_inplace(seq):
        if use_numpy and hasattr(rng, "shuffle"):
            try:
